 for(int i=0;i<6500&&!(bool)Property(current,"Finished");i++){Call(current,"Tick",1f/60);var sim=Property(current,"ReviewSimulation");var b=(Rigidbody)Property(sim,"Body");row.maxHeight=Mathf.Max(row.maxHeight,b.position.y);row.maxBottom=Mathf.Max(row.maxBottom,(float)Call(sim,"Lowest"));if(!captured&&(bool)Field(State(current),"ceilingExited")){CaptureRoute(spec.name,"roof-exit");captured=true;}}
 var final=State(current);row.final=JsonUtility.ToJson(final);row.ceilingBreakthrough=(bool)Field(final,"ceilingBreakthrough");row.ceilingExited=(bool)Field(final,"ceilingExited");row.stopped=(bool)Property(current,"Finished");row.contacts=(string)Call(Property(current,"ReviewSimulation"),"ReviewContactTraceJson");save();CaptureRoute(spec.name,"result");Assert.That((string)Field(final,"physicsFault"),Is.Empty,spec.name);Assert.That(row.stopped,Is.True,spec.name);if(spec.level>=2&&spec.gate)Assert.That(row.ceilingExited,Is.True,spec.name);if(spec.level==1)Assert.That(row.ceilingExited,Is.False,spec.name);
 Call(current,"ShutdownReviewPhysics");current=null;yield return null;yield return null;}
 report.state="COMPLETED";save();}
